#include <bits/stdc++.h>
using namespace std;
using ll = long long;

void solve() {
    int n;
    cin >> n;
    int m = 3 * n;
    vector<ll> a(m);
    for(int i =0;i < m;i++){
        cin >> a[i];
    }
    
    sort(a.rbegin(), a.rend());
    
    vector<ll> pref(m + 1, 0);
    for(int i = 0;i < m;i++){
        pref[i + 1] = pref[i] + a[i];
    }
    
    auto getsum = [&](int k1, int k2){
        int k3 = n - k1 - k2;
        int c6 = k1;
        int c4 = 2 * k2;
        int c3 = 3 * k3;
        
        ll s6 = pref[c6];
        ll s4 = pref[c6 + c4] - pref[c6];
        ll s3 = pref[c6 + c4 + c3] - pref[c6 + c4];
        
        return 6 * s6 + 4 * s4 + 3 * s3;
    };
    
    ll ans = 0;
    
    for(int k1 = 0; k1 <= n; k1++){
        int lo = 0, hi = n - k1;
        while(hi - lo >= 3){
            int m1 = lo + (hi - lo) / 3;
            int m2 = hi - (hi - lo) / 3;
            if(getsum(k1, m1) < getsum(k1, m2)){
                lo = m1;
            }
            else{
                hi = m2;
            }
        }
        for(int k2 = lo; k2 <= hi; k2++){
            ans = max(ans, getsum(k1, k2));
        }
    }
    cout << ans << endl;
    return;
}

int main(){
    int count ;
    cin >> count;
    while(count--){
        solve();
    }
    return 0;
}
